import {completeSalaryProgression084} from './complete-salaries-084.js';
import './simulator-repair-079-ui.js';
import './simulator-repair-078-ui.js';
import{bachelorGraduate,routeKeys,educationRouteLabels,systemCohortLabels,systemCohort,educationMatches}from'./system-match-metrics.js';
import './evidence-benchmark-ui.js';
import './research-comparisons-ui.js';
import{loadCurrentCohort,fetchCohortJSON}from'./current-cohort-loader.js';
import{cohortLabels,filterCurrentRows,currentOutcome,currentCSV}from'./current-match-chart.js';
import{authClient,getPrivateReviewCases}from'./firebase-client.js?v=0.47.0';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Unavailable';
let publicRows=[],privateRows=[],privateCases=new Map(),catalog=new Map(),reviews=new Map(),page=0,filtered=[],userId=null,privateGeneration=0,systemReport=null;
const allRows=()=>[...publicRows,...privateRows],keys=['cohort','field','outcome','education','review'],filters=()=>Object.fromEntries([['query',$('search').value],...keys.map(k=>[k,$(k).value])]);
function saveFilters(){const url=new URL(location.href);const retained=Object.fromEntries(['study','researchCohort','researchQuery','researchCase','researchEducation'].filter(k=>url.searchParams.has(k)).map(k=>[k,url.searchParams.get(k)]));url.search='';for(const[k,v]of Object.entries(retained))url.searchParams.set(k,v);for(const[k,v]of Object.entries(filters()))if(v&&v!=='all')url.searchParams.set(k,v);history.replaceState(null,'',url);}
function flagged(id,p){return reviews.get(id)?.top.some(a=>a.id===p.id&&a.verdict==='needs-clarification');}
function salaryEstimate084(id){const p=completeSalaryProgression084(id);return p?money(p.stages[0].amount)+' / year · qualified-role estimate':'';}
function chip(p,m,lifestyle=false){return '<button class="offer'+(p.supported?'':' candidate')+'" data-model="'+h(m.id)+'" data-career="'+h(p.id)+'"><span>'+h(p.title)+'</span><small>'+h(p.supported?'Supported match':m.followup062?.some(f=>f.id===p.id)?'Specific follow-up · unconfirmed':m.exploration061?.includes(p.id)?'Exploration candidate · unconfirmed':'Browse option · unconfirmed')+' · '+h(routeKeys(catalog.get(p.id)).map(k=>educationRouteLabels[k]).join(' / ')||'Route unassessed')+'</small>'+(flagged(m.id,p)?'<small class="review-flag">Review: needs clarification</small>':'')+'<small>'+salaryEstimate084(p.id)+'</small>'+'</button>';}

function candidateList(m){const existing=new Set([...m.offers.top,...m.offers.other].map(p=>p.id)),ids=(m.exploration061||[]).filter(id=>!existing.has(id)&&educationMatches(catalog.get(id),$('education').value)&&($('field').value==='all'||catalog.get(id)?.fields.includes($('field').value)));return ids.length?'<details class="candidate-pool"><summary>'+ids.length+' further exploration candidates · unconfirmed</summary><p>These come from the full exploration matrix, beyond the first 12 displayed options. They do not count as supported Top.</p>'+ids.map(id=>'<button class="offer candidate" data-model="'+h(m.id)+'" data-career="'+h(id)+'"><span>'+h(catalog.get(id)?.title)+'</span><small>Unconfirmed exploration candidate'+(m.conflicting061?.includes(id)?' · conflicting answer':'')+'</small></button>').join('')+'</details>':'';}
function supportedList(m){const ids=new Set(m.offers.top.map(p=>p.id)),ps=m.offers.supported.filter(p=>!ids.has(p.id));return ps.length?'<details><summary>'+ps.length+' further specifically supported matches</summary><p>These meet the same support requirements but sit below the three highlighted Top positions. All education levels and earnings remain available.</p>'+ps.map(p=>chip(p,m)).join('')+'</details>':'';}
function followupList(m){const fs=m.offers.followups||[];return fs.length?'<details class="candidate-pool"><summary>'+fs.length+' partial-specific follow-ups · not Top</summary><p>Two specific interests supported; one check or more activity examples remain unresolved. No specific No or review hold. Broad disagreement stays visible.</p>'+fs.map(f=>'<button class="offer candidate" data-model="'+h(m.id)+'" data-career="'+h(f.id)+'"><span>'+h(catalog.get(f.id)?.title)+'</span><small>Optional follow-up'+(f.broadDisagreement?' · broad disagreement':'')+'</small></button>').join('')+'</details>':'';}
function renderSystemTotals(){const total=systemReport.summary.all;$('system-counts').textContent='1,000 public models · '+total.top+' with supported Top · '+total.degreeTop+' with bachelor / graduate Top · '+total.topCovers+' whose Top covers lifestyle';$('system-cohort-totals').innerHTML='<table class="cohort-totals"><caption>Development and holdouts · separate groups</caption><thead><tr><th scope="col">Cohort</th><th scope="col">Models</th><th scope="col">Supported Top</th><th scope="col">Bachelor / graduate Top</th><th scope="col">Has broad candidates</th><th scope="col">Has specific follow-ups</th></tr></thead><tbody>'+Object.entries(systemCohortLabels).map(([key,label])=>{const r=systemReport.summary[key];return '<tr><th scope="row">'+h(label)+'</th><td>'+r.models+'</td><td>'+r.top+'</td><td>'+r.degreeTop+'</td><td>'+r.exploration+'</td><td>'+r.followup+'</td></tr>';}).join('')+'</tbody></table><p>Exploration candidates are not supported Top. A model can have both. These totals exclude owner-only models and diagnostic variants and remain fixed while you filter the list below.</p>';}

function render(){
 filtered=filterCurrentRows(allRows(),filters(),catalog,reviews);page=Math.min(page,Math.max(0,Math.ceil(filtered.length/20)-1));
 const n=filtered.length,top=filtered.filter(r=>r.offers.top.length).length,degree=filtered.filter(r=>r.offers.top.some(p=>bachelorGraduate(catalog.get(p.id)))).length,covered=filtered.filter(r=>r.offers.sustaining.length).length;
 $('model-count').textContent=n+' models in this filtered view · '+top+' with supported Top · '+degree+' with bachelor / graduate Top · '+covered+' with a supported lifestyle option';
 const outcomes=[['top-covers','Top match covers','top'],['other-covers','Another supported match covers','other'],['none-cover','No assessed supported match covers','none'],['not-assessed','Not assessed / no supported match','unknown']];
 $('coverage-chart').innerHTML=Object.entries({...systemCohortLabels,diagnostic:'Diagnostic variants',private:'Owner-only'}).map(([phase,label])=>{const rs=filtered.filter(r=>systemCohort(r)===phase);return rs.length?'<div class="coverage-row"><span>'+h(label)+' <b>'+rs.length+'</b></span><div class="coverage-bar">'+outcomes.map(([key,title,cls])=>{const count=rs.filter(r=>currentOutcome(r.offers)===key).length;return count?'<button class="segment '+cls+'" style="width:'+100*count/rs.length+'%" data-outcome="'+key+'" data-cohort="'+(phase==='diagnostic'?'diagnostic049':phase)+'" aria-label="'+h(label+': '+count+' of '+rs.length+' · '+title)+'" title="'+h(count+' of '+rs.length+' · '+title)+'">'+(count/rs.length>.08?count:'')+'</button>':'';}).join('')+'</div></div>':'';}).join('')||'<p>No models in this view.</p>';
 const empty=text=>'<p class="empty">'+text+'</p>';
 $('model-rows').innerHTML=filtered.slice(page*20,page*20+20).map(m=>'<tr><th scope="row"><button class="model-name" data-model="'+h(m.id)+'">'+h(m.name)+' ↗</button><small>'+h(m.id)+'</small><small>'+h(cohortLabels[m.phase]||m.phase)+'</small>'+(m.cohort056?'<small>Structured simulation · not independently reviewed</small>':'')+'<a class="profile-link" href="./model-lab.html?case='+encodeURIComponent(m.id)+'#profile">Profile & answers →</a></th><td>'+(m.offers.top.map(p=>chip(p,m)).join('')||empty('No supported Top match in this view.'))+supportedList(m)+'</td><td>'+((m.offers.other.map(p=>chip(p,m)).join('')||empty('No other displayed options in this view.'))+candidateList(m)+followupList(m))+'</td><td>'+(m.offers.sustaining.map(p=>chip(p,m,true)).join('')||empty('No supported, assessed lifestyle option in this view.'))+'</td></tr>').join('')||'<tr><td colspan="4">No models match these filters.</td></tr>';
 $('page-status').textContent=n?'Models '+(page*20+1)+'–'+Math.min((page+1)*20,n)+' of '+n:'0 models';$('previous').disabled=page===0;$('next').disabled=(page+1)*20>=n;
}
function evidence(p,m){const f=m.followup062?.find(f=>f.id===p.id),followup=f?'<section id="followup-'+h(p.id)+'"><h4>'+h(p.title)+' · optional follow-up</h4><p>Two specific interests supported; '+(f.kind==='specific-check'?'one specific check unresolved.':'more activity examples unresolved.')+(f.broadDisagreement?' Broad interests point elsewhere; this disagreement needs exploration.':'')+'</p><ul>'+f.questions.map(q=>'<li><a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/clarify/'+h(p.id)+'/'+q.index+'">'+h(q.prompt)+'</a></li>').join('')+'</ul></section>':'';const education=catalog.get(p.id)?.education,review=reviews.get(m.id);if(p.candidateOnly)return '<p>'+salaryEstimate084(p.id)+'</p>'+followup+'<article id="career-'+h(p.id)+'" class="career-detail"><h3>'+h(p.title)+'</h3><p><strong>'+h(f?'Optional specific follow-up':'Unconfirmed broad exploration candidate')+'</strong> · '+h(routeKeys(catalog.get(p.id)).map(k=>educationRouteLabels[k]).join(' / '))+'</p><p>'+h(f?'Selected from partial specific evidence, independently of the broad-correlation threshold. ':'Selected by Fieldguide’s broad exploration logic. ')+''+(m.conflicting061?.includes(p.id)?'A recorded specific answer points away from this career.':'Specific interests are not yet sufficiently supported.')+' This is not a supported Top match.</p><a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/profession/'+encodeURIComponent(p.id)+'">Inspect specific evidence, learning routes and earnings →</a></article>';return followup+'<article id="career-'+h(p.id)+'" class="career-detail"><h3>'+h(p.title)+'</h3><p>'+h(p.supported?'Supported match':m.followup062?.some(f=>f.id===p.id)?'Specific follow-up · unconfirmed':m.exploration061?.includes(p.id)?'Exploration candidate · unconfirmed':'Browse option · unconfirmed')+' · '+h(routeKeys(catalog.get(p.id)).map(k=>educationRouteLabels[k]).join(' / ')||'Route unassessed')+'</p>'+(flagged(m.id,p)?'<p class="review-flag">The separate evidence review flags this Top claim for clarification. Its matching status is unchanged.</p>':'')+'<p>Interest correlation: '+(Number.isFinite(p.r)?p.r.toFixed(3):'Unavailable')+'. Interest evidence is not measured aptitude or a probability of success.</p><p><strong>Starting-pay lifestyle check:</strong> '+(p.budget?.covers===true?'Covers the budget under stated assumptions.':p.budget?.covers===false?'Does not cover the budget under stated assumptions.':'Not assessed.')+' '+(Number.isFinite(p.budget?.amount)?money(p.budget.amount)+' / year. ':salaryEstimate084(p.id)+'; first-paid-stage coverage remains unassessed. ')+h(p.budget?.reason||'')+'</p>'+(p.evidence?.length?'<details><summary>Saved supporting answers & evidence</summary><ul>'+p.evidence.map(e=>'<li><strong>'+h(e.text||e.prompt)+'</strong><small>'+h(e.source==='profile-inferred'?'Profile-inferred answer':'Original answer reused unchanged')+' · '+h(e.confidence||'unspecified')+' confidence</small>'+(e.evidence?'<p>'+h(e.evidence)+'</p>':'')+'</li>').join('')+'</ul></details>':'<p>No specific supporting answers recorded for this discovery option.</p>')+(p.contrary?.length?'<p>Some specific answers point away from this career; it remains a discovery option.</p>':'')+'<a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/profession/'+encodeURIComponent(p.id)+'">Explore this profession as the model →</a>'+(review?.reviewed?' · <a href="./calibration-review.html?query='+encodeURIComponent(m.id)+'">Read evidence review →</a>':'')+'</article>';}
function openModel(id,career=''){
 const m=allRows().find(r=>r.id===id);if(!m)return;const visible=filtered.find(r=>r.id===id)?.offers,ps=visible?[...new Map([...visible.top,...visible.other].map(p=>[p.id,p])).values()]:m.first12,review=reviews.get(id);
 if(career&&!ps.some(p=>p.id===career)){const supported=m.supported.find(p=>p.id===career);if(supported)ps.push(supported);else if(m.exploration061?.includes(career)||m.followup062?.some(f=>f.id===career))ps.push({id:career,title:catalog.get(career)?.title,candidateOnly:true});}
 $('detail-content').innerHTML='<h2 id="detail-title">'+h(m.name)+'</h2><p>'+h(m.id)+' · '+h(cohortLabels[m.phase]||m.phase)+'</p><nav class="detail-links"><a href="./model-lab.html?case='+encodeURIComponent(m.id)+'#history">Full profile</a><a href="./model-lab.html?case='+encodeURIComponent(m.id)+'#profile">All original answers</a><a href="../student-view.html?case='+encodeURIComponent(m.id)+'&amp;replay=final#/journey/explore">Current student explorer</a></nav>'+(m.phase==='holdout049'?'<p>Fresh holdout: kept separate and excluded from qualitative calibration.</p>':review?'<p>'+h(review.reviewStatus)+'</p>':'')+'<p>Current offers in the selected education and field view. A recommendation is not a recorded career choice.</p>'+ps.map(p=>evidence(p,m)).join('');
 $('model-detail').showModal();if(career)document.getElementById((m.followup062?.some(f=>f.id===career)?'followup-':'career-')+career)?.scrollIntoView({block:'start'});else $('model-detail').scrollTop=0;
}
function clearPrivate(){privateCases.clear();privateRows=[];$('model-detail').close();$('detail-content').replaceChildren();}
async function loadPrivate(){
 const request=++privateGeneration;clearPrivate();render();const session=await authClient.getSession();if(request!==privateGeneration)return;const user=session.data?.user;userId=user?.id||null;$('chart-signin').hidden=!!user;$('chart-signout').hidden=!user;
 if(user)try{
  const [cases,{currentPrivateMatches}]=await Promise.all([getPrivateReviewCases(),import('./current-private-matches.js')]);const current=(await authClient.getSession()).data?.user;if(request!==privateGeneration||current?.id!==user.id)return;
  const rows=cases.map(currentPrivateMatches);for(const c of cases)privateCases.set(c.id,c);privateRows=rows;$('private-status').textContent='1,000 public base models; 12 diagnostic variants and '+privateRows.length+' owner-only models are available separately.';
 }catch{if(request!==privateGeneration)return;$('private-status').textContent=publicRows.length+' public models. This account could not load owner-only models.';}
 else $('private-status').textContent='1,000 public base models. Sign in to inspect owner-only models separately.';
 render();
}
for(const id of['search',...keys])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;saveFilters();render();});
$('reset').addEventListener('click',()=>{$('search').value='';for(const k of keys)$(k).value='all';page=0;saveFilters();render();});
$('previous').addEventListener('click',()=>{page--;render();$('comparison').scrollIntoView({block:'start'});});$('next').addEventListener('click',()=>{page++;render();$('comparison').scrollIntoView({block:'start'});});
$('close-detail').addEventListener('click',()=>$('model-detail').close());
document.addEventListener('click',e=>{const button=e.target.closest('[data-model]');if(button)openModel(button.dataset.model,button.dataset.career);const segment=e.target.closest('[data-cohort][data-outcome]');if(segment){$('cohort').value=segment.dataset.cohort;$('outcome').value=segment.dataset.outcome;page=0;saveFilters();render();}});
$('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([currentCSV(filtered,reviews,catalog)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='fieldguide-current-model-matches.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('chart-signin').addEventListener('click',async()=>{try{await authClient.googleSignIn();await loadPrivate();}catch{$('private-status').textContent='Sign in on the published Fieldguide site to include owner-only models.';}});$('chart-signout').addEventListener('click',async()=>{++privateGeneration;userId=null;clearPrivate();render();await authClient.signOut();await loadPrivate();});
try{
 const [data,system]=await Promise.all([loadCurrentCohort(),fetchCohortJSON('./system-performance-061.json.gz')]);if(system.runId!==data.runId)throw Error('System metrics and current replay do not agree. Reload the chart.');systemReport=system;if(data.version!=='0.56.0'||new Set(data.rows.map(r=>r.id)).size!==data.rows.length)throw Error('Current result versions do not agree. Reload the chart.');const metrics=new Map(system.rows.map(r=>[r.id,r]));publicRows=data.rows.map(r=>({...r,exploration061:metrics.get(r.id)?.explorationCandidates||[],followup062:metrics.get(r.id)?.followupCandidates||[],conflicting061:metrics.get(r.id)?.conflictingCandidates||[]}));
 const routes=new Map(system.catalog.map(p=>[p.id,p.routes]));catalog=new Map(data.catalog.map(p=>[p.id,{...p,routes:routes.get(p.id)||[]}]));renderSystemTotals();
 $('simulation-notice').textContent='All 441 activity choices have structured bindings; unknown specialty preferences remain unknown. Structured answers only · simulator bindings: '+data.simulation.bindingCoverage.mappedCareers+' / '+data.simulation.bindingCoverage.accessibleCareers+' careers. Unmapped specialist answers remain unfamiliar. The replay covers all mapped subject-aligned career questions; it does not predict typical survey completion. Added profiles have no independent qualitative review. Holdout splits are fixed, but earlier aggregate results have been seen.';
 try{let d=await fetchCohortJSON('./calibration-054-data.json');if(d.$compressedJSON==='gzip-v1')d=await fetchCohortJSON(d.payloadURL);reviews=new Map(d.rows.map(r=>[r.id,r]));}catch{$('review-notice').textContent='The separate evidence review is unavailable. Top matches below retain the current matching status.';}
 $('cohort').innerHTML='<option value="all">All public models · 1,000</option>'+Object.entries(systemCohortLabels).map(([id,label])=>'<option value="'+id+'">'+h(label)+'</option>').join('')+'<option value="all-rows">Public base + diagnostic variants</option><option value="original">Original life-first base profiles</option><option value="expanded">828 structured coverage cases</option>'+Object.entries({...cohortLabels,'original-development':'Original development · 70'}).filter(([id])=>!Object.hasOwn(systemCohortLabels,id)).map(([id,label])=>'<option value="'+id+'">'+h(label)+'</option>').join('');
 $('field').innerHTML='<option value="all">All fields</option>'+data.rows[0].fieldCounts.map(f=>'<option value="'+h(f.id)+'">'+h(f.title)+'</option>').join('');
 const initial=new URL(location.href).searchParams;$('search').value=initial.get('query')||'';for(const k of keys)if([...$(k).options].some(o=>o.value===initial.get(k)))$(k).value=initial.get(k);
 $('replay-date').textContent='Current replay · '+new Date(data.generatedAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});render();
 authClient.watch(next=>{if((next?.id||null)!==userId){++privateGeneration;clearPrivate();render();loadPrivate();}});await loadPrivate();
}catch(e){$('private-status').textContent=e.message;$('model-rows').innerHTML='<tr><td colspan="4">Could not load current results. <a href="./model-lab.html">Open model library</a></td></tr>';}
